import { createSelector } from '@reduxjs/toolkit';

// createSelector takes input selectors and an output function
const selectCartItems = (state) => state.cart.items;
const selectTaxRate = (state) => state.cart.taxRate;

// This only recomputes when cart.items or taxRate changes
const selectCartSummary = createSelector(
  [selectCartItems, selectTaxRate],
  (items, taxRate) => {
    const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    const tax = subtotal * taxRate;
    const total = subtotal + tax;
    const itemCount = items.reduce((count, item) => count + item.quantity, 0);

    return { subtotal, tax, total, itemCount };
  }
);

// Usage in a component
function CartSummary() {
  const { subtotal, tax, total, itemCount } = useSelector(selectCartSummary);
  // ...
}

import { createSelector } from '@reduxjs/toolkit';

// Base selectors
const selectAllProducts = (state) => state.products.items;
const selectFilters = (state) => state.filters;
const selectCartItemIds = (state) => state.cart.itemIds;

// Derived selectors
const selectVisibleProducts = createSelector(
  [selectAllProducts, selectFilters],
  (products, filters) => {
    let result = products;

    if (filters.category) {
      result = result.filter(p => p.category === filters.category);
    }
    if (filters.minPrice !== undefined) {
      result = result.filter(p => p.price >= filters.minPrice);
    }
    if (filters.maxPrice !== undefined) {
      result = result.filter(p => p.price <= filters.maxPrice);
    }
    if (filters.searchQuery) {
      const query = filters.searchQuery.toLowerCase();
      result = result.filter(p => p.name.toLowerCase().includes(query));
    }

    return result;
  }
);

// Selectors that depend on other derived selectors
const selectCartTotalWithDiscount = createSelector(
  [selectVisibleProducts, selectCartItemIds],
  (products, cartIds) => {
    const cartProducts = products.filter(p => cartIds.includes(p.id));
    return cartProducts.reduce((sum, p) => sum + p.price, 0);
  }
);

// Bad: Expensive sort runs on every render
const selectSortedProducts = (state) => 
  [...state.products].sort((a, b) => a.name.localeCompare(b.name));

// Good: Memoized sort only recomputes when products change
const selectSortedProducts = createSelector(
  [(state) => state.products],
  (products) => [...products].sort((a, b) => a.name.localeCompare(b.name))
);

// Even better: Sort once when products load, store sorted order
const selectProductsWithSortOrder = createSelector(
  [(state) => state.products, (state) => state.ui.sortField],
  (products, sortField) => {
    const sorted = [...products];
    if (sortField === 'name') {
      sorted.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortField === 'price') {
      sorted.sort((a, b) => a.price - b.price);
    } else if (sortField === 'date') {
      sorted.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    }
    return sorted;
  }
);
